///|
#borrow(data, mbg_error)
extern "C" fn mbg_bridge_abi_buffer_sum(
  data : Bytes,
  mbg_error : FixedArray[Int],
) -> Int = "mbg_bridge_abi_buffer_sum"

///|
pub fn abi_buffer_sum(data : Bytes) -> Int raise {
  let mbg_error = FixedArray::make(1, 0)
  let value = mbg_bridge_abi_buffer_sum(data, mbg_error)
  if mbg_error[0] != 0 {
    fail("buffer length exceeds supported range")
  }
  value
}

///|
#borrow(mbg_error)
extern "C" fn mbg_bridge_abi_buffer_fill(
  arg0 : Int,
  mbg_error : FixedArray[Int],
) -> Bytes = "mbg_bridge_abi_buffer_fill"

///|
pub fn abi_buffer_fill(arg0 : Int) -> Bytes raise {
  let mbg_error = FixedArray::make(1, 0)
  let value = mbg_bridge_abi_buffer_fill(arg0, mbg_error)
  if mbg_error[0] != 0 {
    fail("negative output buffer capacity")
  }
  value
}

///|
#borrow(mbg_absent)
extern "C" fn mbg_bridge_abi_buffer_view(
  arg0 : Int,
  mbg_absent : FixedArray[Int],
) -> Bytes = "mbg_bridge_abi_buffer_view"

///|
pub fn abi_buffer_view(arg0 : Int) -> Bytes? raise {
  let mbg_absent = FixedArray::make(1, 0)
  let value = mbg_bridge_abi_buffer_view(arg0, mbg_absent)
  if mbg_absent[0] == 1 {
    None
  } else if mbg_absent[0] != 0 {
    fail("invalid returned buffer length or pointer")
  } else {
    Some(value)
  }
}

